import { Injectable } from '@angular/core';
import { APPLICATION_STATE } from '../globals';

@Injectable({
  providedIn: 'root',
})
export class GlobalService {
  constructor() {}
  setAppState(newState: string): void {
    APPLICATION_STATE == newState;
  }
}
